package io.github.diodeme.ji.security.secret;

/** External secret source used by master-key adapters. */
public interface SecretSource {
    SecretValue read(String reference);

    enum Kind {
        DESKTOP_OS_CREDENTIAL_STORE,
        POSIX_FILE_0600,
        ENVIRONMENT,
        SYSTEMD_CREDENTIAL,
        DOCKER_SECRET,
        EXTERNAL_SECRET_MANAGER
    }
}
